def sequence(n: int) -> int:
    if n <= 0:
        raise ValueError("n must be a positive integer")

    # Base cases
    p = [0] * (n + 1)
    p[1] = 1
    if n >= 2:
        p[2] = 1

    for i in range(3, n + 1):
        prev = p[i - 1]
        first_term = p[p[prev]]          # P_{P_{i-1}}
        second_term = p[i - prev]         # P_{i - P_{i-1}}
        p[i] = first_term + second_term

    return p[n]

