def max_aggregate(data):
    # Dictionary to store name -> sum_of_scores
    aggregates = {}

    # Iterate over the list of tuples
    for name, score in data:
        if name not in aggregates:
            aggregates[name] = 0
        aggregates[name] += score

    # Find the person with the maximum aggregate score
    max_name = None
    max_score = -1

    for name, total in aggregates.items():
        if total > max_score:
            max_score = total
            max_name = name

    return (max_name, max_score)

