def check_expression(expr: str) -> bool:
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}

    for ch in expr:
        if ch in "([{":          # opening bracket
            stack.append(ch)
        elif ch in ")]}":        # closing bracket
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
        else:                    # ignore other characters (optional)
            continue

    return len(stack) == 0

